client = AppAIGatewayClient(
    appID: appID,
    baseURL: baseURL,
    // App Attest proves the request comes from your app on a real
    // device. An API key works in the simulator, for testing.
    authMode: apiKey.map { .apiKey(key: $0) } ?? .appAttestInstall
)

let (bytes, response) = try await client.withAuthorizedRequest(
    provider: slug(model),
    providerPath: path,
    body: body,
    contentType: "application/json"
) { request in
    // Headers may be added to a signed request; its URL and body may not change.
    var request = request
    for (name, value) in headers { request.setValue(value, forHTTPHeaderField: name) }
    return try await URLSession.shared.bytes(for: request)
}

let lines = try await stream(
    model,
    path: ProviderPaths.chat(model.provider),
    body: anthropic ? anthropicBody(turns, model) : chatCompletionsBody(turns, model),
    headers: anthropic ? ["anthropic-version": "2023-06-01"] : [:]
)
// Both stream server-sent events: `data: {json}` lines.
for try await line in lines where line.hasPrefix("data:") {
    let event = Data(line.dropFirst(5).utf8)
    if line.hasSuffix("[DONE]") { break }
    if let text = try anthropic ? anthropicText(event) : chatCompletionsText(event) {
        continuation.yield(text)
    }
}

