client = AppAIGatewayClient(
    appID: appID,
    baseURL: baseURL,
    // App Attest proves the request comes from your app on a real
    // device. An API key works in the simulator, for testing.
    authMode: apiKey.map { .apiKey(key: $0) } ?? .appAttestInstall
)

let request = try await client.authorizedRealtimeRequest(provider: slug(model), model: model.model)
let task = URLSession.shared.webSocketTask(with: request)
// A single audio delta can be large; the gateway caps provider frames at 1 MiB.
task.maximumMessageSize = 1 << 20
task.resume()

sender = Task {
    for await pcm in audio.chunks {
        try? await socket.send(["type": "input_audio_buffer.append", "audio": pcm.base64EncodedString()])
    }
}

case "response.output_audio.delta":
    // While you talk over an answer, what is still in flight of it
    // belongs to the response the gateway is cancelling.
    if phase != .hearing, let pcm = (event["delta"] as? String).flatMap({ Data(base64Encoded: $0) }) {
        audio.play(pcm)
    }
